import requests
terms=['"KPC-producing" "oral gentamicin" decolonization','"colistin-resistant" "intestinal decolonization" Klebsiella','"oral decontamination" KPC Klebsiella mortality','aminoglycoside decontamination colistin-resistant KPC carriers']
for q in terms:
 u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi'
 d=requests.get(u,params={'db':'pubmed','term':q,'retmode':'json','retmax':20,'sort':'relevance'},timeout=20).json()['esearchresult']
 ids=d['idlist']; print('\nQUERY',q,'IDS',ids[:10])
 if ids:
  s=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids[:10]),'retmode':'json'},timeout=20).json()['result']
  for i in ids[:10]: print(i,s[i].get('title'),s[i].get('pubdate'))

import requests,xml.etree.ElementTree as ET
u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi'
r=requests.get(u,params={'db':'pubmed','id':'27494911','rettype':'abstract','retmode':'xml'},timeout=20)
root=ET.fromstring(r.text)
for a in root.findall('.//ArticleTitle'): print('TITLE:', ''.join(a.itertext()))
for a in root.findall('.//Abstract/AbstractText'): print('ABSTRACT:',a.attrib, ''.join(a.itertext()))
for a in root.findall('.//Author'): 
 names=' '.join((a.findtext('LastName') or '',a.findtext('Initials') or ''))
 if names.strip(): print('AUTHOR:',names)
